DROP TRIGGER standard_seat_valid;
CREATE TRIGGER standard_seat_valid BEFORE INSERT ON seat_claims WHEN NEW.status IN('held','confirmed') AND NOT EXISTS(SELECT 1 FROM departures d JOIN vehicles v ON v.id=d.vehicle_id LEFT JOIN standard_departure_layouts l ON l.departure_id=d.id WHERE d.id=NEW.departure_id AND d.status='published' AND unixepoch(d.depart_at)>unixepoch('now') AND NEW.seat_number BETWEEN 1 AND COALESCE(l.capacity,v.capacity)) BEGIN SELECT RAISE(ABORT,'seat_unavailable'); END;
ALTER TABLE departures ADD COLUMN driver_override_id TEXT REFERENCES standard_drivers(id);
ALTER TABLE departures ADD COLUMN suppress_default_driver INTEGER NOT NULL DEFAULT 0 CHECK(suppress_default_driver IN(0,1));
CREATE TRIGGER ground_departure_driver AFTER INSERT ON departures WHEN NEW.suppress_default_driver=0 BEGIN INSERT INTO standard_departure_drivers(departure_id,operator_id,driver_id,driver_name,assigned_by) SELECT NEW.id,v.operator_id,dr.id,dr.full_name,(SELECT user_id FROM memberships WHERE operator_id=v.operator_id AND role='owner' LIMIT 1) FROM vehicles v JOIN standard_drivers dr ON dr.id=COALESCE(NEW.driver_override_id,v.default_driver_id) AND dr.operator_id=v.operator_id AND dr.status='active' AND dr.license_expires_on>=date(NEW.depart_at,'-5 hours') WHERE v.id=NEW.vehicle_id; END;
CREATE TRIGGER ground_driver_slot_overlap BEFORE INSERT ON standard_vehicle_slots WHEN NEW.active=1 AND NEW.departure_id IS NOT NULL AND EXISTS(SELECT 1 FROM standard_departure_drivers current JOIN standard_departure_drivers other ON other.driver_id=current.driver_id AND other.departure_id<>current.departure_id JOIN standard_vehicle_slots os ON os.departure_id=other.departure_id AND os.active=1 WHERE current.departure_id=NEW.departure_id AND os.starts_at<NEW.ends_at AND os.ends_at>NEW.starts_at) BEGIN SELECT RAISE(ABORT,'trip_driver_conflict'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0037_ground_operations');
